  1 │ /**
  2 │  * Which checkouts the host may run Git in. The agent's sandbox can write its worktree (its `.git` pointer and nested
  3 │  * repositories included) but nothing outside it, and Git reads the configuration of whatever repository `.git` leads
  4 │  * to, so a planted one is a way to run a command on the host. Pure file-system checks, shared by the worktree Git helper
  5 │  * (`worktrunk/git.ts`), the session's own Git helpers and the checkpoint manager; no dependency on any of them.
  6 │  */
  7 │ import * as fs from "node:fs";
  8 │ import * as path from "node:path";
  9 │ 
 10 │ function inside(root: string, candidate: string): boolean {
 11 │   return candidate === root || candidate.startsWith(root + path.sep);
 12 │ }
 13 │ 
 14 │ /** Variables that change how Git reads pathspecs; an inherited one would turn a `:(top)` magic pathspec literal or case-insensitive. */
 15 │ export const PATHSPEC_MODE_ENV: readonly string[] = ["GIT_LITERAL_PATHSPECS", "GIT_GLOB_PATHSPECS", "GIT_NOGLOB_PATHSPECS", "GIT_ICASE_PATHSPECS"];
 16 │ 
 17 │ /**
 18 │  * The path in a `.git` pointer file, read the way Git reads it: the content must start with `gitdir: `, only the
 19 │  * trailing line break is dropped, and nothing else is trimmed. A guard that trimmed would resolve a different directory
 20 │  * than Git does for `gitdir: x ` and could be shown a harmless one; such a pointer is refused instead.
 21 │  */
 22 │ export function parseGitfilePointer(content: string): string | undefined {
 23 │   if (!content.startsWith("gitdir: ")) return undefined;
 24 │   const target = content.slice("gitdir: ".length).replace(/\r?\n$/, "");
 25 │   if (target === "" || target !== target.trim() || /[\0\r\n]/.test(target)) return undefined;
 26 │   return target;
 27 │ }
 28 │ 
 29 │ /** Repositories this process has opened and their linked worktrees (from `git worktree list`, run where the operator is). */
 30 │ const knownCommonDirs = new Set<string>();
 31 │ const knownLinkedWorktrees = new Set<string>();
 32 │ export function rememberRepository(commonDir: string, linkedWorktrees: readonly string[]): void {
 33 │   knownCommonDirs.add(commonDir);
 34 │   for (const dir of linkedWorktrees) {
 35 │     try { knownLinkedWorktrees.add(fs.realpathSync(dir)); } catch { /* gone: nothing to run Git in */ }
 36 │   }
 37 │ }
 38 │ 
 39 │ /**
 40 │  * Whether `root`, which has a `.git` DIRECTORY, is really a linked worktree whose `.git` FILE the agent replaced: it is
 41 │  * a linked worktree of a repository this process opened, or it is registered (with its `.git` file) in an enclosing
 42 │  * repository's or an opened repository's worktree registry. A registry entry that cannot be read is skipped on its own,
 43 │  * never ending the scan of the others.
 44 │  */
 45 │ function replacedWorktreeReason(root: string): string | undefined {
 46 │   if (knownLinkedWorktrees.has(root)) return `${root} is a linked worktree whose .git file was replaced by a repository`;
 47 │   const registries = new Set<string>(Array.from(knownCommonDirs, (common) => path.join(common, "worktrees")));
 48 │   for (let dir = path.dirname(root); ; dir = path.dirname(dir)) {
 49 │     registries.add(path.join(dir, ".git", "worktrees"));
 50 │     if (path.dirname(dir) === dir) break;
 51 │   }
 52 │   for (const registry of registries) {
 53 │     let names: string[];
 54 │     try { names = fs.readdirSync(registry); } catch { continue; } // no registry here
 55 │     for (const name of names) {
 56 │       try {
 57 │         const recorded = fs.readFileSync(path.join(registry, name, "gitdir"), "utf8").trim();
 58 │         if (path.basename(recorded) === ".git" && fs.realpathSync(path.dirname(path.resolve(registry, name, recorded))) === root) {
 59 │           return `${root} is a linked worktree registered in ${path.dirname(path.dirname(registry))} whose .git file was replaced by a repository`;
 60 │         }
 61 │       } catch { /* a stale entry (its directory was deleted by hand) */ }
 62 │     }
 63 │   }
 64 │   return undefined;
 65 │ }
 66 │ 
 67 │ /**
 68 │  * The agent runs in a sandbox that can write its worktree, `.git` pointer file and any nested repository included, but
 69 │  * nothing outside it. Git reads the configuration of whatever repository `.git` leads to; a planted one can carry
 70 │  * commands (`filter.*.clean`, `commit.gpgsign` with `gpg.program`) that would run on the host. A checkout is trusted only
 71 │  * when every `.git` file on the way up is a plain pointer to a Git directory OUTSIDE the outermost linked worktree
 72 │  * (outside what the agent can write) that points back at it (`gitdir` of a `<common>/worktrees/<name>` entry, or
 73 │  * `core.worktree` of a separate or submodule Git directory), and no repository with a real `.git` directory sits inside
 74 │  * a linked worktree. `gitDir`/`workTree` are the verified pair for the nearest `.git` file: Git is then run against them
 75 │  * directly, so a pointer rewritten after this check is not re-read.
 76 │  */
 77 │ export function verifyCheckout(cwd: string): { reason?: string; gitDir?: string; workTree?: string } {
 78 │   let start: string;
 79 │   try { start = fs.realpathSync(cwd); } catch { return {}; }
 80 │   const files: string[] = [];
 81 │   const directories: string[] = [];
 82 │   for (let dir = start; ; dir = path.dirname(dir)) {
 83 │     try {
 84 │       if (fs.lstatSync(path.join(dir, ".git")).isDirectory()) directories.push(dir); else files.push(dir);
 85 │     } catch { /* no .git here */ }
 86 │     if (path.dirname(dir) === dir) break;
 87 │   }
 88 │   // The agent-writable boundary is the outermost LINKED worktree (its `.git` leads to `<common>/worktrees/<name>`). A
 89 │   // `.git` file above it (a bare-repository layout `project/.git` -> `.bare`) is the operator's, not the agent's.
 90 │   const isLinkedRoot = (root: string): boolean => {
 91 │     try {
 92 │       const target = parseGitfilePointer(fs.readFileSync(path.join(root, ".git"), "utf8"));
 93 │       return target !== undefined && path.basename(path.dirname(fs.realpathSync(path.resolve(root, target)))) === "worktrees";
 94 │     } catch { return false; }
 95 │   };
 96 │   const outer = [...files].reverse().find(isLinkedRoot) ?? files[files.length - 1];
 97 │   if (!outer) {
 98 │     // A plain repository (or none). But a registered linked worktree whose `.git` file the agent replaced by a repository
 99 │     // looks exactly like one: the main repository's worktree registry says it is not.
100 │     for (const root of directories) {
101 │       const replaced = replacedWorktreeReason(root);
102 │       if (replaced) return { reason: replaced };
103 │     }
104 │     return {};
105 │   }
106 │   files.splice(0, files.length, ...files.filter((root) => inside(outer, root)));
107 │   const planted = directories.find((dir) => inside(outer, dir));
108 │   if (planted) return { reason: `${planted} is a repository nested inside the linked worktree ${outer}` };
109 │   let pinned: { gitDir: string; workTree: string } | undefined;
110 │   for (const root of files) {
111 │     const dotGit = path.join(root, ".git");
112 │     try {
113 │       const stat = fs.lstatSync(dotGit);
114 │       if (stat.isSymbolicLink() || !stat.isFile() || stat.size > 4096) return { reason: `${dotGit} is not a plain pointer file` };
115 │       const target = parseGitfilePointer(fs.readFileSync(dotGit, "utf8"));
116 │       if (target === undefined) return { reason: `${dotGit} is not a well-formed gitdir pointer` };
117 │       const admin = fs.realpathSync(path.resolve(root, target));
118 │       if (inside(outer, admin)) return { reason: `${dotGit} leads into a repository inside the worktree itself` };
119 │       let pointsBack = false;
120 │       if (path.basename(path.dirname(admin)) === "worktrees") {
121 │         const common = fs.realpathSync(path.dirname(path.dirname(admin)));
122 │         if (inside(outer, common)) return { reason: `${dotGit} leads into a repository inside the worktree itself` };
123 │         pointsBack = fs.realpathSync(path.resolve(admin, fs.readFileSync(path.join(admin, "gitdir"), "utf8").trim())) === path.join(root, ".git");
124 │       } else {
125 │         const configured = /^\s*worktree\s*=\s*(.+?)\s*$/m.exec(fs.readFileSync(path.join(admin, "config"), "utf8"));
126 │         pointsBack = configured !== null && fs.realpathSync(path.resolve(admin, configured[1])) === root;
127 │       }
128 │       if (!pointsBack) return { reason: `the Git directory behind ${dotGit} does not point back at it` };
129 │       pinned ??= { gitDir: admin, workTree: root };
130 │     } catch {
131 │       return { reason: `${dotGit} could not be verified` };
132 │     }
133 │   }
134 │   return pinned ?? {};
135 │ }
