137 │ /** `git submodule status` lines as {path, initialised}; a path may contain spaces. */
138 │ export function parseSubmoduleStatus(listing: string): Array<{ path: string; initialised: boolean }> {
139 │   const found: Array<{ path: string; initialised: boolean }> = [];
140 │   for (const line of listing.split("\n")) {
141 │     const match = /^(.)[0-9a-f]{40,64} (.*?)(?: \(.*\))?$/.exec(line);
142 │     if (match) found.push({ path: match[2], initialised: match[1] !== "-" });
143 │   }
144 │   return found;
145 │ }
