147 │ /** The reason `cwd` is not a trusted checkout (see `verifyCheckout`), or undefined. */
148 │ export function untrustedCheckoutReason(cwd: string): string | undefined {
149 │   return verifyCheckout(cwd).reason;
150 │ }
  1 │ /**
  2 │  * The one place the worktree feature runs Git.
  3 │  *
  4 │  * Every call pins the configuration that could otherwise turn a repository into code execution or change what a
  5 │  * result means: no replace objects, no hooks (`core.hooksPath` plus the Git 2.54+ configured-hook switch), no
  6 │  * fsmonitor, no external transport helpers, no inherited repository-selecting environment. Refs and paths that
  7 │  * come from a user are passed after `--end-of-options`; callers also validate them first (see paths.ts), so a
  8 │  * name such as `--upload-pack=...` is refused before it reaches Git.
  9 │  *
 10 │  * Trust boundary: the agent's sandbox can write its worktree, `.git` pointer and nested repositories included, so
 11 │  * `git()` first refuses a checkout whose `.git` leads anywhere the agent could have planted (`untrustedCheckoutReason`),
 12 │  * and then runs Git against the VERIFIED git directory (`--git-dir`/`--work-tree`), so a pointer rewritten after the
 13 │  * check is never re-read. Past that, `.git/config`, the user's and the system's Git configuration are trusted as Git trusts them. Hooks,
 14 │  * fsmonitor and external transports are pinned off because a checkout can reach them, but a `filter.<name>.clean`
 15 │  * command configured in that trusted configuration still runs when `git status` compares content; `.gitattributes`
 16 │  * can only name a filter, never define its command.
 17 │  */
 18 │ import { spawnSync } from "node:child_process";
 19 │ import * as fs from "node:fs";
 20 │ import * as path from "node:path";
 21 │ import { envWithoutConfiguredHooks } from "../core/git_hook_guard.js";
 22 │ import { PATHSPEC_MODE_ENV, parseSubmoduleStatus, untrustedCheckoutReason, verifyCheckout } from "../core/checkout_trust.js";
 23 │ export { parseSubmoduleStatus, untrustedCheckoutReason };
 24 │ import { redactSecrets } from "../ui.js";
 25 │ 
 26 │ /** Hook events Nexus-initiated worktree commands must never fire. */
 27 │ export const SUPPRESSED_HOOK_EVENTS = [
 28 │   "post-checkout", "pre-commit", "prepare-commit-msg", "commit-msg", "post-commit", "post-merge",
 29 │   "pre-merge-commit", "pre-rebase", "post-rewrite", "reference-transaction", "post-index-change", "pre-auto-gc",
 30 │ ] as const;
 31 │ 
 32 │ export const PINNED_GIT_FLAGS: readonly string[] = [
 33 │   "--no-replace-objects",
 34 │   "--no-optional-locks",
 35 │   "-c", "core.hooksPath=/dev/null",
 36 │   "-c", "core.fsmonitor=false",
 37 │   "-c", "protocol.ext.allow=never",
 38 │   "-c", "submodule.recurse=false",
 39 │   "-c", "core.quotePath=false",
 40 │ ];
 41 │ 
 42 │ /** Variables that would redirect Git at another repository, object store, diff driver or ref namespace, or change how pathspecs are read. */
 43 │ export const SCRUBBED_ENV = [
 44 │   "GIT_DIR", "GIT_WORK_TREE", "GIT_INDEX_FILE", "GIT_OBJECT_DIRECTORY", "GIT_ALTERNATE_OBJECT_DIRECTORIES",
 45 │   "GIT_COMMON_DIR", "GIT_NAMESPACE", "GIT_EXTERNAL_DIFF", "GIT_REPLACE_REF_BASE", "GIT_PAGER", "GIT_SSH_COMMAND",
 46 │   "GIT_ASKPASS", "GIT_EDITOR", "GIT_SEQUENCE_EDITOR", "GIT_PREFIX", "GIT_CEILING_DIRECTORIES",
 47 │   ...PATHSPEC_MODE_ENV,
 48 │ ];
 49 │ 
 50 │ export class GitError extends Error {
 51 │   constructor(message: string, readonly status: number | null, readonly args: readonly string[]) {
 52 │     super(message);
 53 │     this.name = "GitError";
 54 │   }
 55 │ }
 56 │ 
 57 │ /** A checkout (or a repository nested in one) whose Git directory the sandboxed agent could have planted. */
 58 │ export class UntrustedCheckoutError extends GitError {
 59 │   constructor(cwd: string, reason: string, args: readonly string[]) {
 60 │     super(`refusing to run Git in ${cwd}: it is not a trusted worktree of this repository (${reason})`, null, args);
 61 │     this.name = "UntrustedCheckoutError";
 62 │   }
 63 │ }
 64 │ 
 65 │ export interface GitResult { status: number | null; stdout: string; stderr: string; timedOut: boolean }
 66 │ 
 67 │ export interface GitOptions {
 68 │   /** Milliseconds before the child is killed (default 30 s). */
 69 │   timeoutMs?: number;
 70 │   /** Do not throw on a non-zero exit. */
 71 │   allowFailure?: boolean;
 72 │   /** Extra environment (applied after scrubbing); never the repository selectors. */
 73 │   env?: Record<string, string>;
 74 │   maxBuffer?: number;
 75 │   /** Text for the child's standard input (for `--stdin` forms). */
 76 │   input?: string;
 77 │ }
 78 │ 
 79 │ /** Submodule levels `nestedRepositoryReason` walks before refusing rather than guessing. */
 80 │ const MAX_SUBMODULE_DEPTH = 4;
 81 │ 
 82 │ /**
 83 │  * Whether a repository the agent could have planted sits below `dir`: a gitlink in the index or an untracked directory
 84 │  * holding a `.git`. Git itself descends into submodules when it reports status, reading their configuration, so this
 85 │  * runs before every status. Undefined when `dir` is not an agent-writable checkout or nothing is wrong.
 86 │  */
 87 │ export function nestedRepositoryReason(dir: string, depth = 0): string | undefined {
 88 │   const own = verifyCheckout(dir);
 89 │   if (own.reason) return own.reason;
 90 │   if (!own.gitDir) return undefined;
 91 │   if (depth > MAX_SUBMODULE_DEPTH) return `submodules are nested more than ${MAX_SUBMODULE_DEPTH} levels deep below ${dir}`;
 92 │   const candidates = new Set<string>();
 93 │   for (const entry of git(dir, ["ls-files", "-s", "-z"]).stdout.split("\0")) {
 94 │     const match = /^160000 [0-9a-f]+ \d\t(.+)$/.exec(entry);
 95 │     if (match) candidates.add(match[1]);
 96 │   }
 97 │   // Without `--directory` Git still lists a nested repository (at any depth) as one `dir/` entry.
 98 │   for (const entry of git(dir, ["ls-files", "-o", "--exclude-standard", "-z"]).stdout.split("\0")) {
 99 │     if (entry.endsWith("/")) candidates.add(entry.slice(0, -1));
100 │   }
101 │   for (const rel of candidates) {
102 │     const sub = path.join(dir, rel);
103 │     try { fs.lstatSync(path.join(sub, ".git")); } catch { continue; } // an ordinary directory, or a submodule not initialised here
104 │     const reason = nestedRepositoryReason(sub, depth + 1); // a planted repository can sit below a legitimate submodule too
105 │     if (reason) return reason;
106 │   }
107 │   return undefined;
108 │ }
109 │ 
110 │ let hookEnvCache: { key: string; env: NodeJS.ProcessEnv } | undefined;
111 │ 
112 │ function baseEnv(): NodeJS.ProcessEnv {
113 │   // Computed per process-environment value: envWithoutConfiguredHooks spawns `git --version`.
114 │   const key = process.env.GIT_CONFIG_PARAMETERS ?? "";
115 │   if (!hookEnvCache || hookEnvCache.key !== key) {
116 │     hookEnvCache = { key, env: envWithoutConfiguredHooks(process.cwd(), SUPPRESSED_HOOK_EVENTS) };
117 │   }
118 │   const env: NodeJS.ProcessEnv = { ...hookEnvCache.env };
119 │   for (const name of SCRUBBED_ENV) delete env[name];
120 │   env.GIT_TERMINAL_PROMPT = "0";
121 │   env.LC_ALL = "C";
122 │   env.LANGUAGE = "C";
123 │   return env;
124 │ }
125 │ 
126 │ export function git(cwd: string, args: readonly string[], options: GitOptions = {}): GitResult {
127 │   const checkout = verifyCheckout(cwd);
128 │   if (checkout.reason) throw new UntrustedCheckoutError(cwd, checkout.reason, args);
129 │   const pin = checkout.gitDir ? ["--git-dir", checkout.gitDir, "--work-tree", checkout.workTree!] : [];
130 │   const result = spawnSync("git", [...PINNED_GIT_FLAGS, ...pin, ...args], {
131 │     cwd,
132 │     encoding: "utf8",
133 │     stdio: ["pipe", "pipe", "pipe"],
134 │     input: options.input ?? "",
135 │     env: { ...baseEnv(), ...(options.env ?? {}) },
136 │     timeout: options.timeoutMs ?? 30_000,
137 │     maxBuffer: options.maxBuffer ?? 32 * 1024 * 1024,
138 │   });
139 │   const timedOut = (result.error as NodeJS.ErrnoException | undefined)?.code === "ETIMEDOUT";
140 │   const out: GitResult = { status: result.status, stdout: result.stdout ?? "", stderr: result.stderr ?? "", timedOut };
141 │   if (result.error && !timedOut) throw new GitError(`git could not run: ${(result.error as Error).message}`, null, args);
142 │   if (!options.allowFailure && (timedOut || result.status !== 0)) {
143 │     const detail = timedOut ? "timed out" : redactSecrets(out.stderr.trim().split("\n")[0] ?? "").slice(0, 300);
144 │     throw new GitError(`git ${args[0] ?? ""} failed: ${detail || `exit ${result.status}`}`, result.status, args);
145 │   }
146 │   return out;
147 │ }
148 │ 
149 │ /** `git ...` stdout, trimmed of one trailing newline. */
150 │ export function gitOut(cwd: string, args: readonly string[], options: GitOptions = {}): string {
151 │   return git(cwd, args, options).stdout.replace(/\n$/, "");
152 │ }

